import Foundation

/// Where health data comes from.
public enum HealthDataKind: String, Sendable, Hashable {
    /// The user's HealthKit store.
    case healthKit
    /// Generated by ``SampleHealthDataSource``, for previews, demos and the simulator.
    case sample
}

/// Whether HealthKit would show the permission sheet for a source's types.
public enum HealthAuthorizationStatus: String, Sendable, Hashable {
    /// The sheet has not been shown for every type yet: call ``HealthDataSource/requestAuthorization()``.
    case shouldRequest
    /// The sheet was shown. HealthKit never says whether reading was allowed; denied types just read as empty.
    case requested
    case unknown
}

public enum HealthDataError: Error, Sendable, Hashable, LocalizedError {
    /// HealthKit is not available on this device (iPad without Health, Mac, or a restricted device).
    case healthDataUnavailable

    public var errorDescription: String? {
        switch self {
        case .healthDataUnavailable:
            "Health data is not available on this device."
        }
    }
}

/// A source of health data for the cards: ``HealthKitDataSource`` reads HealthKit, ``SampleHealthDataSource``
/// generates plausible, deterministic data. Write your own to read from a server or a fixture.
///
/// Units follow ``HealthMetric``. Days and weeks follow ``calendar``.
public protocol HealthDataSource: Sendable {
    var kind: HealthDataKind { get }

    /// The calendar that defines days and weeks.
    var calendar: Calendar { get }

    /// Asks for permission to read. Sources that need none return at once.
    func requestAuthorization() async throws

    /// Whether ``requestAuthorization()`` would still show the permission sheet.
    func authorizationStatus() async throws -> HealthAuthorizationStatus

    /// A statistics collection: one point per day or week overlapping `interval`, oldest first. Sums include
    /// buckets without data as zero; averages leave them out (see ``HealthAggregation/normalize(_:aggregation:interval:bucket:calendar:)``).
    func statistics(_ metric: HealthMetric, in interval: DateInterval, bucket: StatisticsBucket) async throws -> [MetricPoint]

    /// Heart rate measurements, resting heart rate and heart rate variability for the day containing `date`.
    func heartRate(on date: Date) async throws -> HeartRateSummary

    /// The night that ended on the morning of the day containing `date`, or `nil` without sleep data.
    func sleep(forNightEndingOn date: Date) async throws -> SleepNight?

    /// The activity rings of the day containing `date`, or `nil` without data.
    func activityRings(on date: Date) async throws -> ActivityRings?

    /// Workouts that started in `interval`, newest first.
    func workouts(in interval: DateInterval) async throws -> [Workout]
}

extension HealthDataSource {
    /// Data from ``SampleHealthDataSource``: the UI should say so.
    public var isSampleData: Bool { kind == .sample }

    /// Daily points for the `days` days ending on the day containing `date`.
    public func dailyStatistics(_ metric: HealthMetric, days: Int, endingOn date: Date) async throws -> [MetricPoint] {
        let lastDay = calendar.startOfDay(for: date)
        let end = calendar.date(byAdding: .day, value: 1, to: lastDay) ?? lastDay
        let start = calendar.date(byAdding: .day, value: -(Swift.max(1, days) - 1), to: lastDay) ?? lastDay
        return try await statistics(metric, in: DateInterval(start: start, end: end), bucket: .day)
    }

    /// Weekly points for the `weeks` calendar weeks ending with the week containing `date`.
    public func weeklyStatistics(_ metric: HealthMetric, weeks: Int, endingOn date: Date) async throws -> [MetricPoint] {
        let thisWeek = HealthAggregation.bucketStart(for: date, bucket: .week, calendar: calendar)
        let end = calendar.date(byAdding: .weekOfYear, value: 1, to: thisWeek) ?? thisWeek
        let start = calendar.date(byAdding: .weekOfYear, value: -(Swift.max(1, weeks) - 1), to: thisWeek) ?? thisWeek
        return try await statistics(metric, in: DateInterval(start: start, end: end), bucket: .week)
    }

    /// This week against last week for a metric, ending on the day containing `date`.
    public func weeklyTrend(_ metric: HealthMetric, endingOn date: Date) async throws -> WeeklyTrend {
        let points = try await dailyStatistics(metric, days: 14, endingOn: date)
        return WeeklyTrend(metric: metric, dailyPoints: points, endingOn: date, calendar: calendar)
    }

    /// Up to `count` nights, oldest first, ending with the night that ended on the morning of the day containing
    /// `date`. Nights without data are left out.
    public func recentNights(endingOn date: Date, count: Int = 7) async throws -> [SleepNight] {
        let calendar = self.calendar
        let lastDay = calendar.startOfDay(for: date)
        let nights = Swift.max(0, count)
        return try await withThrowingTaskGroup(of: (Int, SleepNight?).self) { group in
            for offset in 0..<nights {
                let day = calendar.date(byAdding: .day, value: -offset, to: lastDay) ?? lastDay
                group.addTask {
                    let night = try await self.sleep(forNightEndingOn: day)
                    return (offset, night)
                }
            }
            var found: [(Int, SleepNight)] = []
            for try await (offset, night) in group {
                if let night {
                    found.append((offset, night))
                }
            }
            return found.sorted { $0.0 > $1.0 }.map { $0.1 }
        }
    }

    /// Loads everything the cards show for the day containing `date`, with the queries running in parallel.
    public func snapshot(for date: Date = Date()) async throws -> HealthSnapshot {
        let calendar = self.calendar
        let today = calendar.startOfDay(for: date)
        let tomorrow = calendar.date(byAdding: .day, value: 1, to: today) ?? today
        let weekStart = calendar.date(byAdding: .day, value: -6, to: today) ?? today
        let todayInterval = DateInterval(start: today, end: tomorrow)

        async let steps = dailyStatistics(.steps, days: 14, endingOn: date)
        async let energy = dailyStatistics(.activeEnergy, days: 14, endingOn: date)
        async let exercise = dailyStatistics(.exerciseTime, days: 14, endingOn: date)
        async let distance = statistics(.walkingRunningDistance, in: todayInterval, bucket: .day)
        async let heartRateSummary = heartRate(on: date)
        async let rings = activityRings(on: date)
        async let nights = recentNights(endingOn: date, count: 7)
        async let recentWorkouts = workouts(in: DateInterval(start: weekStart, end: tomorrow))

        let stepPoints = try await steps
        let energyPoints = try await energy
        let exercisePoints = try await exercise
        let distancePoints = try await distance
        let recent = try await nights
        let todayRings = try await rings
        let todayHeartRate = try await heartRateSummary
        let weekWorkouts = try await recentWorkouts

        return HealthSnapshot(
            date: date,
            calendar: calendar,
            stepPoints: stepPoints,
            energyPoints: energyPoints,
            exercisePoints: exercisePoints,
            distancePoints: distancePoints,
            rings: todayRings,
            heartRate: todayHeartRate,
            recentNights: recent,
            workouts: weekWorkouts
        )
    }
}

/// HealthKit when the device has it, sample data otherwise (on the Mac, for example).
public func makeDefaultHealthDataSource(calendar: Calendar = .current) -> any HealthDataSource {
    #if canImport(HealthKit) && (os(iOS) || os(watchOS))
    if HealthKitDataSource.isAvailable {
        return HealthKitDataSource(calendar: calendar)
    }
    #endif
    return SampleHealthDataSource(calendar: calendar)
}
